UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Antonio was basically our saving grace in a messy custody battle. During our consult he took the time to hear our story and ensured us he had the knowledge to help us. He did not disappoint. He was knowledgeable, always prepared, and made us feel important.","author":"","url":"https://a-circelli-law.ca/testimonials/"},{"text":"I am extremely fortunate and grateful to have had Antonio Circelli represent me in what was a long and contentious separation and divorce process. His guidance, dedication, commitment and genuine concern led to what ultimately became a balanced and fair resolution, without the need for trial. Thank you Antonio.","author":"","url":"https://a-circelli-law.ca/testimonials/"},{"text":"I have experience working with Tony for the past 11 years. Tony has always been approachable, willing to listen and provide sound guidance and advice. Tony takes the time to understand the situation, while working to solve problems in a collaborative and cooperative way.","author":"","url":"https://a-circelli-law.ca/testimonials/"}]')), updated_at = datetime('now') WHERE slug = 'a-circelli-law-guelph' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I had a great experience working with Akash and his employees for my recent first home purchase. Everything was explained clearly, and the process was handled efficiently from start to finish.","author":"","url":"https://adhillonlaw.com/"},{"text":"Akash Dhillon and his team are highly professional and dedicated. Their commitment to client care and achieving the best possible outcomes is clear. I would highly recommend them to anyone seeking a reliable and trustworthy criminal lawyer.","author":"","url":"https://adhillonlaw.com/"},{"text":"We are incredibly grateful to Akash and his team for the exceptional support and representation he provided during a youth matter involving a close family member.","author":"","url":"https://adhillonlaw.com/"}]')), updated_at = datetime('now') WHERE slug = 'a-dhillon-law-brampton' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"My property was sold in 20 days of listing and I was not sure on who to use to do my real estate paperwork, I was recommended by a friend of mine to use Steve. I had a very professional and quick dealing with Steve Mattoo. I will highly recommend him to everyone.","author":"","url":"https://mattoolaw.com/"},{"text":"I used Amrik as my Real estate lawyer when I bought my house, He did a great job in explaining how the paper work process works and I had a smooth process of buying the new house. Great Job.. He definitely would get my recommendation.","author":"","url":"https://mattoolaw.com/"},{"text":"I was nervous about the purchase of my new house but Mr. Mattoo made me feel at ease. I found his staff to be competent and very professional. I would recommend his services to anybody who is buying or selling a house.","author":"","url":"https://mattoolaw.com/"}]')), updated_at = datetime('now') WHERE slug = 'a-s-mattoo-and-associates-law-office-kamloops' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Mark Kim was amazing, his knowledge of family law and his compassion made this difficult period more tolerable. Both myself and ex were put at ease during the process. Highly recommend Mark.","author":"P.P.","url":"https://www.familylawyerdivorcetoronto.com/client-testimonials/"},{"text":"Mark assisted me with my separation proceedings. He was always professional and non-judgemental. I had absolutely no experience with the situation and he was very patient at explaining every step to me. I would recommend his services to those able to access them.","author":"S.P.","url":"https://www.familylawyerdivorcetoronto.com/client-testimonials/"},{"text":"Mark Zamrij provided professional and detail-oriented family law services during my child custody case. Mark is a very strategic family lawyer and was helpful in advising me in my objectives for my case.","author":"M.L.","url":"https://www.familylawyerdivorcetoronto.com/client-testimonials/"}]')), updated_at = datetime('now') WHERE slug = 'aaries-family-law-kingston' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"URGENT INTRA-COMPANY TRANSFER : We retained Abramovich Immigration Law to prepare an urgent intra-company transfer application in the midst of COVID-19. Lev and Ksenia provided our company with first-rate guidance, assessing our options and setting out a clear path forward.","author":"","url":"https://atimmigrationlaw.com/"},{"text":"BIG PICTURE ADVICE : Lev has acted as our immigration counsel for the last eight years. He provides us with legal advice on all of our immigration matters, including recruitment, retention and overall strategy. He also helps our workers transition to permanent residency. On every individual matter, he is always looking at the big picture.","author":"","url":"https://atimmigrationlaw.com/"},{"text":"TURNED BAD SITUATION AROUND : When we initially came to Canada, we had received bad immigration advice that led to a deportation. While we hired Lev too late to stop the deportation, he quickly worked with my employer to obtain an LMIA and an authorization to return to Canada in a very short period of time.","author":"","url":"https://atimmigrationlaw.com/"}]')), updated_at = datetime('now') WHERE slug = 'abramovich-immigration-law-toronto' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Affordable, professional and experienced. I have used these guys for years and they always get the very best outcome. I have used many other ticket lawyers and I have to write this review to help others. This team is the real deal.","author":"","url":"https://acostalegalservices.com/"},{"text":"Can''t say much more than the results that they were able to produce for me, withdrawn. Great experience overall, easy to get started and nothing that I had to worry about. Everything was taken care of, especially the ticket. They were able to get the results that I wanted, so no complaints from me.","author":"","url":"https://acostalegalservices.com/"},{"text":"From the moment I contacted them they assured me everything would be taken care of. . They went over above and beyond thanks so much for your professional service","author":"","url":"https://acostalegalservices.com/"}]')), updated_at = datetime('now') WHERE slug = 'acosta-legal-services-north-york' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"My experience with Laura was amazing! She put in so much hard work, she never gave up and was truly resilient! I''m super impressed. Thanks Laura you definitely helped this family out.","author":"Hailey B.","url":"https://www.advocatelawyers.ca/"},{"text":"If you are looking for a very professional, well known and respected attorney Maurice Collard is definitely your guy. I was a client of his and I can not explain how grateful I am for what he has done for me.","author":"Steven S.","url":"https://www.advocatelawyers.ca/reviews"},{"text":"I cannot express how thankful I am to have Laura take my case. She didn''t fly through legal words I wouldn''t have known and explained everything as if I was talking to a friend.","author":"Don D.","url":"https://www.advocatelawyers.ca/reviews"}]')), updated_at = datetime('now') WHERE slug = 'advocate-law-calgary' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
