UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Greetings Shabnam, my wife just got her open work visa and is on the job hunt. Thanks for your quick and speedy turn around. You guys made this a breeze.","author":"","url":"https://thevisa.ca/"},{"text":"My thanks to you and your team, Shabnam. My wife and I have just entered Canada and received our documents. I am now a Federal Skilled Worker ;) We couldn’t have done this without you.","author":"","url":"https://thevisa.ca/"},{"text":"Ms. Akrami, I would like to convey my sincerest gratitude with respect to my matter. It was handled with an efficiency and care I was not expecting. I am glad to see hard working and truly dedicated professionals still exist.","author":"","url":"https://thevisa.ca/about-us/reviews/"}]')), updated_at = datetime('now') WHERE slug = 'akrami-and-associates-mississauga' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"One of my good friends referred me to Alice Huynh''s law firm and I''m very grateful and happy to have found such an amazing and attentive lawyer. I''m newly divorced and she made the process simple and easy for me. Something that made me very anxious, anyone going through a divorce would know exactly what I''m talking about.","author":"","url":"https://alicehuynhlaw.com/en/"},{"text":"I am so glad I found Alice as a lawyer that specializes in family law for my dad. My dad does not know how to speak english well, so the fact that Alice can speak Vietnamese fluently to my dad was a huge plus! It took away a lot of information that can be loss through translation.","author":"","url":"https://alicehuynhlaw.com/en/"},{"text":"[I] very much appreciated having Alice as my lawyer. The attribute that impressed me the most was her integrity. She was sympathetic about the unfairness of my case but none the less stuck to her professional opinion... She could have easily strung me along and sent me a big bill in the end.","author":"","url":"https://alicehuynhlaw.com/en/"}]')), updated_at = datetime('now') WHERE slug = 'alice-huynh-law-corporation-vancouver' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Joanne is the best person I could have asked for to work through our cohabitation agreement with. Professional, kind, easy to speak to and throughout the process I always felt well informed.” Linstead P.","author":"","url":"https://alignfamilylaw.ca/testimonials/"},{"text":"At a very difficult time in my life, Joanne and her team at Align Family Law have been compassionate, articulate, very knowledgeable, and we even managed to share some laughs! She made a very painful process as painless as possible.” Tracey T.","author":"","url":"https://alignfamilylaw.ca/testimonials/"},{"text":"Joanne was great. I think her resolution seeking approach is a fantastic way to find solutions to these difficult issues. The guidance and advice from Joanne was spot on.” Dave C.","author":"","url":"https://alignfamilylaw.ca/testimonials/"}]')), updated_at = datetime('now') WHERE slug = 'align-family-law' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Joe Iwanicki took my case on and immediately made me feel confident with an intelligent approach combined with a confident demeanour. Together, we fought what seemed like a hopeless fight for three years against a much larger party with limitless funds and resources.","author":"","url":"https://alloy.law/"},{"text":"Greg helped us close the transaction on our first rental property. He was prompt and prepared. Any questions we had were answered thoroughly and he communicated throughout the whole process. We look forward to working with him to acquire new properties.","author":"","url":"https://alloy.law/"},{"text":"Greg recently supported us during the sale of our home. He provided excellent advice throughout the process and thoroughly explained all of the considerations involved in both the sale of our previous home and the purchase of our new one.","author":"","url":"https://alloy.law/"}]')), updated_at = datetime('now') WHERE slug = 'alloy-llp-calgary' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I have confidently referred clients to Terry & his staff for over 20 years. Very professional, very prompt & very knowledgeable. Terry has always made himself available to answer my questions.","author":"","url":"https://ambassadorlaw.ca/"},{"text":"Sidhu and Associates have always been awesome notaries and i will continue to use them and recommend them to family and friends Dawn is very good at her job, Kevin and I appreciate all that you did to get our mortgage paperwork done quickly and efficiently.","author":"","url":"https://ambassadorlaw.ca/"},{"text":"We sold and bought a house last year and also created wills at Sidhu & Associates. Everyone that we worked with there was professional and helpful, especially Ashley! They were able to work around our busy work schedules and meet our quick timelines with the house sale and purchase.","author":"","url":"https://ambassadorlaw.ca/"}]')), updated_at = datetime('now') WHERE slug = 'ambassador-law-corporation-abbotsford' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
