UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"In 2005, I was involved in a serious car accident which left me unable to work. Initially, I tried to deal with the insurance claims on my own, but when the insurance company continued to deny my benefits, I felt helpless, frustrated and in need of income replacement to support my family.","author":"","url":"https://www.bergellaw.com/resources/testimonials/"},{"text":"I injured my hand as a result of a defective product and recovered over $500,000 thanks to the Bergel law firm. From the moment I arrived at the first interview, my injury case was handled in a professional way. The lawyers and staff really did listen to me. J.C.","author":"North Y.","url":"https://www.bergellaw.com/resources/testimonials/"},{"text":"Thank you to Ilan Bergel for his hard work on my personal Injury case. The expectations set out at the very beginning, including approximate length of the case and financial award became reality. Bergel, Magence LLP got me what I was looking for and kept my expectations real.","author":"","url":"https://www.bergellaw.com/resources/testimonials/"}]')), updated_at = datetime('now') WHERE slug = 'bergel-magence-guelph' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I have known Mr Preyra for over 17 yrs and he has represented me on several occasions. He is dedicated, assertive, professional, and realistic. I will recommend Alan as a Lawyer to any one who requires legal assistance in any capacity. Continue in excellence Alan.","author":"","url":"https://www.bplawyers.ca/resources/testimonials"},{"text":"Alan, I want to thank you again for all the excellent work you have done for me in reaching a suitable settlement in my case. Without your warm style, experience, perspective and compassion, I don’t think I could have made it so far. I am truly blessed when I was referred to you.","author":"","url":"https://www.bplawyers.ca/resources/testimonials"},{"text":"When I lost my leg in a motorcycle accident I was referred to Kurt Bergmanis. My prior lawyer had told me my case was too tough. Kurt and his team were with me every step of the way. He told me not to worry and that my future would be secure.","author":"","url":"https://www.bplawyers.ca/resources/testimonials"}]')), updated_at = datetime('now') WHERE slug = 'bergmanis-preyra-llp-toronto' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Thank you for your prompt legal advise. I highly recommended my families and friends to Bernard Lau and Co. Law... Thank you for your prompt legal advise. I highly recommended my families and friends to Bernard Lau and Co. Law Office. Looking forward to meet up with you next week with my cousin!","author":"","url":"https://www.bernardlau.com/"},{"text":"I’m a first time home buyer and needed a legal representative. To be honest, I was clueless to which direction... I’m a first time home buyer and needed a legal representative. To be honest, I was clueless to which direction to take to complete my property purchase.","author":"","url":"https://www.bernardlau.com/"},{"text":"Bernard, Regine and Christina are super helpful and efficient. They''ve helped me twice for property transactions and both of them... Bernard, Regine and Christina are super helpful and efficient. They''ve helped me twice for property transactions and both of them were going smooth without any issue.","author":"","url":"https://www.bernardlau.com/"}]')), updated_at = datetime('now') WHERE slug = 'bernard-lau-and-co-law-office-richmond' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Rick was very nice to work with. He was very patient and always explained everything in a way we could understand. I would recommend Rick to all my friends and family.","author":"","url":"https://bickhramlitigation.com/"},{"text":"I was referred by another estate lawyer who had worked with Rick and had nothing but praise for his talent. I wasn’t disappointed, Rick got the job done and listened to my concerns throughout the entire process. I highly recommend him.","author":"","url":"https://bickhramlitigation.com/reviews-2"},{"text":"Highly recommended 5 star firm that valued my business from start to finish. Rick and Tera are extremely knowledgeable and guided me every step of the way and provided me with the results I wanted regarding my family law matter. Couldn’t be happier.","author":"","url":"https://bickhramlitigation.com/reviews-2"}]')), updated_at = datetime('now') WHERE slug = 'bickhram-litigation-mississauga' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I’ve used Birdsell Grant for many years for a multitude of different legal dealings. They have been nothing but professional and extremely proficient. I highly recommend them.","author":"","url":"https://birdsell.ca/"},{"text":"We sold our house and used Birdsell Grant and had a great experience. They are friendly, fast and great at what they do. I would recommend to anyone looking for a lawyer.","author":"","url":"https://birdsell.ca/"},{"text":"We were very lucky to have the Birdsell Grant team for a real estate transaction with a number of quirks and very tight timelines. They were rather incredible in both quality and speed and extremely pleasant as well. An easy 11/10!","author":"","url":"https://birdsell.ca/"}]')), updated_at = datetime('now') WHERE slug = 'birdsell-grant-llp-edmonton' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
