UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I had a great experience at Carraig Law Group. As an Asylum seeker, I was supported all through, from start to a successful finish! I appreciated the open communication lines, extra time during physical meetings, attention accorded to my case, I was listened to, etc. I would recommend you any day any time!","author":"","url":"https://www.carraiglaw.com/"},{"text":"Ronald was able to help me with very clear organized advice and peace of mind with several legal options, along with pros and cons of each. Hopefully, there are no further disputes, however if there is, I’m writing him right away and taking action.","author":"","url":"https://www.carraiglaw.com/"}]')), updated_at = datetime('now') WHERE slug = 'carraig-law-group-llp-vancouver' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
