UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I count my blessings I found Trish Johnson. She is professional, knowledgeable, thorough, efficient, and she conducts her work with such empathy, patience, and understanding. Having Trish in my corner has made complex and sometimes overwhelming situations manageable. Thank you Trish!","author":"","url":"https://www.crossroadslaw.ca/"},{"text":"Jenna Lalani at Crossroads law has been very professional and efficient through the whole process of my divorce. She has taken the time to review all aspects of my case so that I had a good understanding of the process. I would strongly recommend Jenna if you are looking for a family lawyer.","author":"","url":"https://www.crossroadslaw.ca/"},{"text":"Thank you, Amanda, and Crossroads Law! I only hope you know how much you helped me in the short visit we had. When I need help again, I''ll be looking you up!","author":"D.B.","url":"https://www.crossroadslaw.ca/reviews/"}]')), updated_at = datetime('now') WHERE slug = 'crossroads-law-vancouver' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
