UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I''ve been a client of Michael Day for years. He''s very knowledgeable and professional. He''s been involved in numerous real estate closings and other legal matters for my family. Would definitely recommend him!","author":"","url":"https://dayborg.com/"},{"text":"I have worked with Mike Day for over 38 years. Mike is a consistently good lawyer and I recommend him to my friends. As a real estate broker with over 350 salespeople, I use Mike Day personally.","author":"","url":"https://dayborg.com/"},{"text":"The entire firm has always provided professional, personal and expert services for our business and personal requirements . I would highly recommend Day + Borg LLP for the handling of all legal situations.","author":"","url":"https://dayborg.com/"}]')), updated_at = datetime('now') WHERE slug = 'day-borg-llp-mississauga' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Great team, we have sold, bought and refinanced with this law firm and every time our transactions were very smooth. We are always very happy with Stan de Krupe and his team, highly recommended!!","author":"","url":"https://dekrupelaw.ca/"},{"text":"Loved the team, we were buying and selling, nothing short of excellent. Stan and Eva were great at answering all the questions and we could not be happier!!","author":"","url":"https://dekrupelaw.ca/"},{"text":"We have used De Krupe Law in both Toronto and Newmarket (we moved) and were always happy with their service. Stan always takes time to explain everything and answer all questions. Never had an email go unanswered with them. Thanks! A++","author":"","url":"https://dekrupelaw.ca/"}]')), updated_at = datetime('now') WHERE slug = 'de-krupe-law-north-york' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"My experience with Deborah Todd has been incredibly positive. Deborah knows her stuff and is easy to work with. She is sensitive to my needs and keeps things going smoothly and is completely professional at all times. I have no reservations about recommending her to friends and colleagues.","author":"","url":"https://www.deborahtoddlaw.com/testimonials/"},{"text":"Deborah Todd and team are highly skilled in family law. They take a practical, no-nonsense approach that is in the best interest of their clients. We highly recommend Deborah Todd.","author":"","url":"https://www.deborahtoddlaw.com/testimonials/"},{"text":"Deborah Todd has been my lawyer since at least 2001 she was recommended to me by an acquaintance whom also is a lawyer and the fact that she was recommended by one of her peers meant a lot to me.","author":"","url":"https://www.deborahtoddlaw.com/testimonials/"}]')), updated_at = datetime('now') WHERE slug = 'deborah-todd-law-corporation' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I had the pleasure of working with Hailee Barber, she is absolutely amazing! Very knowledgeable, honest, and compassionate, she will steer you in the right direction without making you feel like you are stuck between a rock and a hard place.","author":"","url":"https://dsfamilylaw.ca/reviews"},{"text":"I would highly recommend Demas Schaefer to anyone who is going through a divorce and is seeking strong, skilled and results oriented representation. During an extremely stressful time in my life, Sean and Tanya guided me with timely, direct and competent advice.","author":"","url":"https://dsfamilylaw.ca/reviews"},{"text":"Just wanted to thank Mark and Sue for all their help. They’ve been amazing in the service they provided and I highly recommend them to anyone! J.A.","author":"","url":"https://dsfamilylaw.ca/reviews"}]')), updated_at = datetime('now') WHERE slug = 'demas-schaefer-family-lawyers-edmonton' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"For anyone looking for a Kamloops Lawyer, I would recommend Lisa. She is very personable and friendly and also a top real real estate lawyer. Thanks to Lisa, Amber and Shelley for making my home purchase so painless.","author":"","url":"https://denhamlawoffice.com/"},{"text":"Lisa helped me with some estate planning for my mother and a new will for me. I travel a lot for work, and I appreciated how she found time in her schedule for me. I recommend Lisa for anything wills and estate related in BC.","author":"","url":"https://denhamlawoffice.com/"},{"text":"Thanks to Lisa and Cynthia for a great experience selling my home in Kamloops. I recommend Lisa Denham Law for all your Notary Public needs.","author":"","url":"https://denhamlawoffice.com/"}]')), updated_at = datetime('now') WHERE slug = 'denham-law-office' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Deutschmann de Koning are personal injury lawyers who represented me in a successful motorcycle accident claim. They were very competent and professional and I would use them again without hesitation.","author":"John H.","url":"https://www.ddinjurylaw.com/"},{"text":"Met with Nick recent and quickly met Rob as I was going in their office and for lawyers they are very down to earth guys and very helpful and very friendly. And sure just start with them but I have a good feeling about it all...","author":"Kw N.","url":"https://www.ddinjurylaw.com/"},{"text":"SP was a front seat passenger in a car that was driven by her husband. Her husband failed to stop the car at a stop sign and was struck by another car with a driver and 3 passengers that had the right of way and was proceeding through the intersection.","author":"","url":"https://www.ddinjurylaw.com/client-reviews-testimonials"}]')), updated_at = datetime('now') WHERE slug = 'deutschmann-de-koning-law-kitchener' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Dhasi Law Firm was fantastic to work with for my home sale and purchase closings. They were transparent, responsive, and guided me through every step of the process. Everything was handled smoothly and on time. Highly recommend!","author":"","url":"https://www.dhasilaw.com/"},{"text":"I’ve worked with Dhasi Law a few times for buying and selling a home, and every experience has been amazing. Barinder makes the whole process easy and stress-free. He kept us updated, explained everything in detail, and always had great solutions ready.","author":"","url":"https://www.dhasilaw.com/"},{"text":"Dhasi Law Professional Corporation provided exceptional service for our real estate transaction. Barinder Dhasi demonstrated strong attention to detail, professionalism, and clear communication from start to finish. The closing process was seamless. We would confidently recommend their services.","author":"","url":"https://www.dhasilaw.com/"}]')), updated_at = datetime('now') WHERE slug = 'dhasi-law-family-lawyer-brampton-brampton' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"very good experience with mam. give genuine advice. I recommend it to everyone. THANK YOU","author":"","url":"https://dhimanlaw.com/"},{"text":"I strongly recommend Dhiman Law. They are amazing and reasonable. They accepted my matter with a very tight deadline, and it was reassuring to know that they didn''t view me as simply another file. Really happy with their professional services.","author":"","url":"https://dhimanlaw.com/"},{"text":"Mrs. Inderjit is very professional and helpful. She provided me excellent service even on a short notice. I wanted a letter, and she had kept all the details already drafted and ready which helped me saved my time too.","author":"","url":"https://dhimanlaw.com/"}]')), updated_at = datetime('now') WHERE slug = 'dhiman-law-professional-corporation-ottawa' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
