UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I had an excellent experience working with Tushaar and Raman. From the very beginning, they demonstrated a high level of professionalism, knowledge, and genuine care for their clients. What really stood out was how responsive they were—calls and emails were always returned promptly, and I never felt left waiting or uncertain about the status of my matter.","author":"","url":"https://goldwynlaw.ca/"},{"text":"The team did an amazing job on closing of my condo The Goldwyn team is highly recommended","author":"","url":"https://goldwynlaw.ca/"},{"text":"My husband and I worked with this firm for the legal process of purchasing our home, and our lawyer was excellent. The entire experience was smooth, seamless, and very well organized. They answered all our questions, were always reachable, and guided us clearly through every step.","author":"","url":"https://goldwynlaw.ca/"}]')), updated_at = datetime('now') WHERE slug = 'goldwyn-law-professional-corporation-markham' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Having been at our wits end having faced obstacle after obstacle in completing the requirements for an LMIA application for our firm, we reached out to GOOSELAW Immigration law firm. Donovan was extremely professional and gave us excellent advice.","author":"","url":"https://gooselaw.com/reviews/"},{"text":"Our experience with GOOSELAW Immigration law firm has been instrumental in securing work authorization in Canada. Getting our work visa approved was a long, complicated process but the GOOSELAW Immigration team was amazing!","author":"","url":"https://gooselaw.com/reviews/"},{"text":"Working with GOOSELAW™ Immigration law firm has been a pleasure from start to finish. The team’s professionalism and commitment to client satisfaction are truly commendable. The fast and secure online service ensures a smooth application process, and their expert guidance has led to a 100% success rate for our employees’ work permits.","author":"","url":"https://gooselaw.com/reviews/"}]')), updated_at = datetime('now') WHERE slug = 'gooselaw-immigration-law-firm-mississauga' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Thank you Gosal & Company for all your help with my WCB claim as well as my CPP file. I couldn’t have done it successfully without your expertise, and hard work. Much appreciated. I highly recommend Gosal & Company.","author":"","url":"https://www.wcblawyers.com/hear-from-our-clients/"},{"text":"Gosal & Co did an absolutely amazing job with my mom''s WCB case. They were very helpful, understanding and thorough which achieved a positive result for us. Even going forward, they are great with follow ups and continued information. I would highly recommend them!","author":"","url":"https://www.wcblawyers.com/hear-from-our-clients/"},{"text":"My experience with Gosal & Company was very good. My biggest mistake was not getting them sooner. I highly recommend hiring Gosal & Company at the start of your claim.","author":"","url":"https://www.wcblawyers.com/hear-from-our-clients/"}]')), updated_at = datetime('now') WHERE slug = 'gosal-and-company-surrey' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"As someone who had no idea how the system works, George helped me out and did an exceptional job with my case, which was withdrawn. I''m grateful for your help. I highly recommend him if you need someone who can help you with any case.","author":"","url":"https://georgegray.ca/testimonials/"},{"text":"The last several months were probably the darkest time of my whole life … Mr. Gray explained all the possibilities and the right move I should make at our very first meeting. The whole process was smooth and stress-free, and the case was resolved with the best result we could get.","author":"","url":"https://georgegray.ca/testimonials/"},{"text":"Professionalism, altruism, and a great capacity to help is the least of what I can recognize … a great lawyer and a great human being. I thank God for putting the opportunity to receive his help in my way.","author":"","url":"https://georgegray.ca/testimonials/"}]')), updated_at = datetime('now') WHERE slug = 'gray-criminal-defence-toronto' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I had an outstanding experience working with Green and Spiegel on my visa application. From the very beginning, their team, especially Cristina Guida and Lysandra Deschenes, provided exceptional support. I was truly impressed by how fast the entire process was handled. They were incredibly organized, efficient, and knowledgeable, making sure that every detail was addressed.","author":"","url":"https://gands.com/about-us/our-reputation/"},{"text":"We were looking for an Immigration Law firm to help us with our immigration needs. I found Green and Spiegel on google and based on their google reviews I decided to partner with them. The decision to go with them was absolutely fruitful. Under the able leadership of Jonathan Green, we were able to successfully achieve all our immigration needs.","author":"","url":"https://gands.com/about-us/our-reputation/"}]')), updated_at = datetime('now') WHERE slug = 'green-and-spiegel-llp-toronto' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"The people at Grover Law Firm were awesome in helping me getting my settlement. Miss Summer Abbasi and Steve Grover were professional in helping me.","author":"","url":"https://www.groverlawfirm.com/"},{"text":"Grover Law firm has exceptional service. Went above and beyond. Very easy to work with and empathetic to my situation. The outcome was more than expected. I would highly recommend to anyone needing an injury lawyer.","author":"","url":"https://www.groverlawfirm.com/"},{"text":"Highly recommend Grover Law! Davie especially created an unforgettable experience with his upbeat personality and ability to make us feel comfortable. I’m not saying I’d name my next child after him, but I’m not ruling it out. Great guy, great firm.","author":"","url":"https://www.groverlawfirm.com/"}]')), updated_at = datetime('now') WHERE slug = 'grover-law-firm-calgary' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Moving back to Alberta, we needed to redo our wills. Having met Shannon through the process we were blown away! This would be the third time we’ve updated wills, etc. in our lifetime. Shannon and her team are the most thorough and compassionate lawyers we’ve ever had the privilege to deal with.","author":"","url":"https://www.gunnlawgroup.ca/"},{"text":"Very helpful and professional explaining my case and getting through it all, I''m thankful for all there help in winning my case. highly recommend.","author":"","url":"https://www.gunnlawgroup.ca/"},{"text":"Highly recommend!! I can''t say enough good about this law firm! Everybody was excellent & very prompt at getting back to us when we had questions. Shannon Gunn Emery is an outstanding lawyer & her caring personality & professionalism helped keep us calm in a very stressful situation!","author":"","url":"https://www.gunnlawgroup.ca/"}]')), updated_at = datetime('now') WHERE slug = 'gunn-law-group-edmonton' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I am highly thankful to Gurna Law Corporation for getting me an approval for my post graduation open work permit. It was by no means a straightforward case. However, Mr. Saravpreet Singh and his team made the process very comfortable and easy for me. I would rank them very highly for their professionalism and care for my case.","author":"","url":"https://gurnalaw.ca/"},{"text":"Today my Open Work Permit was approved, and I am incredibly relieved. I was in a very difficult and vulnerable situation, filled with fear and uncertainty about my future. Gurna Law Corporation worked tirelessly on my case and supported me every step of the way.","author":"","url":"https://gurnalaw.ca/"},{"text":"Our initial consultation has been great. Hopefully things does turn out well with the immigration process. I have to highlight that their price is reasonable without compromising quality and good customer service! Helen Navarro","author":"","url":"https://gurnalaw.ca/"}]')), updated_at = datetime('now') WHERE slug = 'gurna-law-corporation-surrey' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
