UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I needed to get the custody of my child and Handa Law helped me with it. Thankfully my child is with me now. Highly recommend their service.","author":"","url":"https://www.handalawpc.ca/"},{"text":"Would highly recommend Handa Law ! Very professional and respectful lawyer ! She is super resourceful with her work. Definitely would trust her with my issues/work.","author":"","url":"https://www.handalawpc.ca/"},{"text":"Kritika at Handa Law is very professional, understanding, knowledgeable and a great pleasure to deal with. I highly recommend her and the services she has to offer and will be using her for any possible future transactions. Thank you Kritika!","author":"","url":"https://www.handalawpc.ca/"}]')), updated_at = datetime('now') WHERE slug = 'handa-law-professional-corporation-brampton' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
