UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Rhia Dhindsa I’ve had a positive experience working with Kamalie Law. Shayan and Karan are great litigators who are knowledgeable, professional, and efficient. I would definetly recommended Kamalie Law to anyone in need of legal services","author":"","url":"https://kamalielaw.ca/"},{"text":"Cindy McLean Highly recommend this team for legal disputes. They helped me with a breach of contract issue and offered me practical advice along the way.","author":"","url":"https://kamalielaw.ca/"},{"text":"Sina Valiaghaie I feel so fortunate to have met Shayan. He is such a skilled and professional lawyer, and he has helped me a lot. I’m truly grateful to you, Shayan.","author":"","url":"https://kamalielaw.ca/"}]')), updated_at = datetime('now') WHERE slug = 'kamalie-law-north-york' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Kaysi was exceptional during one of the most difficult times for our family. She worked tirelessly on my husband’s case and successfully helped him to get out of it when we were losing hope.","author":"","url":"https://kaysifagan.com/testimonials"},{"text":"I can’t thank Kaysi and her team enough for everything they’ve done for me.","author":"","url":"https://kaysifagan.com/testimonials"},{"text":"Kaysi Fagan is hands down the most professional capable lawyer I have had experience with.","author":"","url":"https://kaysifagan.com/testimonials"}]')), updated_at = datetime('now') WHERE slug = 'kaysi-fagan-calgary' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Amazing customer service! Travis and the team went above and beyond for us. We used Travis to complete a commercial real estate transaction. The transaction went smoothly and closed on time. Thanks Travis and team for making it such an easy process for us. WD S","author":"","url":"https://khlawgroup.com/"}]')), updated_at = datetime('now') WHERE slug = 'kh-dunkley-law-group-calgary' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I was astounded at how well Pranav could not only help me with my legal issue, but in fact was cheaper than other firms I looked at. His attention to detail and customer service is inspiring. I highly recommend Khemka Law.","author":"F.B.","url":"https://khemkalaw.com/"},{"text":"We used the legal services of Khemka Law three times in the last year for real estate transactions. 2 of the 3 transactions had RPR (real property report) issues which Pranav was able to rectify. Pranav provides great customer service and conducts himself in a very professional manner.","author":"R.G.","url":"https://khemkalaw.com/"}]')), updated_at = datetime('now') WHERE slug = 'khemka-law-calgary' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Fariya F I had a good experience working with Jonathan and Reem from Kormans LLP. I had a very tight deadline to get a pre-construction review completed. Jonathan was quick to respond to my queries and Reem provided exceptional service within the short time-period. Highly recommended!","author":"","url":"https://www.kormans.ca/"},{"text":"Hasan Arshad I recently closed a Condo and used Kormans LLP’s services. Both Christina and Reem handled my case with great professionalism and care. They thoroughly guided me through the process and helped even with stuff like document pick up etc. Very responsive and efficient. Recommended!","author":"","url":"https://www.kormans.ca/"},{"text":"Arushi Singh The team at Kormans LLP are so helpful and responsive. I worked closest with Heena, Yashkaran, and Ammal. Special shoutout and thanks to the three of them for their support, patience, and professionalism!","author":"","url":"https://www.kormans.ca/services/corporate-law/contract-review-and-drafting"}]')), updated_at = datetime('now') WHERE slug = 'kormans-llp' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I have had the pleasure of working with Jerry and his team on a number of Canadian immigration matters over the last two years. I have always found his guidance and counsel to be accurate, professional, timely, and easy to understand in the complex and ever changing world of immigration law.","author":"","url":"https://kreindlerlaw.com/testimonials/"},{"text":"Many thanks to you and your staff for all the work you did in preparing my application. Is at in the imigration waiting room at Toronto Airport waiting for them to process my application and had the opportunity to see what happens to individuals whose application was not as thoroughly prepared as mine was.","author":"","url":"https://kreindlerlaw.com/testimonials/"},{"text":"Our employees visa application went very smoothly. Thanks again, Jerry, for another job well done.","author":"","url":"https://kreindlerlaw.com/testimonials/"}]')), updated_at = datetime('now') WHERE slug = 'kreindler-law-toronto' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"We had a great experience with Kris! He is very professional and knowledgeable and walked us through the entire process. Highly recommend!","author":"","url":"https://kslawoffice.ca/"},{"text":"Kris is a great guy, very polite, patient, and knows his thing. My experience has been nothing less. Highly recommended.","author":"","url":"https://kslawoffice.ca/"},{"text":"Very knowledgeable, honest and delivers on time. I will always go back and will suggest his name to all I know.","author":"","url":"https://kslawoffice.ca/"}]')), updated_at = datetime('now') WHERE slug = 'ks-law-professional-corporation-etobicoke' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I needed an employment lawyer to provide me some advices and I had a timeline to hit. When I emailed Jenson Leung, he replied within a few hours and was able to arrange a 30 min consultation with me promptly, even though he''s very busy.","author":"","url":"https://www.kswlawyers.ca/testimonials"},{"text":"I had a wonderful experience working with KSW Law Firm. Fiona and Mahum were incredibly professional, prompt and very helpful. I highly recommend KSW Law! Their team’s professionalism is incredible.","author":"","url":"https://www.kswlawyers.ca/testimonials"},{"text":"This law firm worked with me for quite a few years to settle my problems. They are a good law firm for anyone to hire. Thankyou Kanchan. Thankyou Cindy.","author":"","url":"https://www.kswlawyers.ca/testimonials"}]')), updated_at = datetime('now') WHERE slug = 'ksw-lawyers' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"My personal experience with Personal Law Group has been tremendous. Dealing with estate matters was completely foreign to me. Chantal and her team have been amazing every step of the way in guiding me through this process. I highly recommend this law firm.","author":"","url":"https://estatelawboutique.com/"},{"text":"5 Stars! Chantal and her staff prepared Wills and Powers of Attorney for my husband and myself on short notice before Christmas, and they had everything finalized within 3 days! 👍 Professional and courteous, highly recommended.","author":"","url":"https://estatelawboutique.com/"},{"text":"Very impressed by the efficient and friendly services offered by Chantal and her team. They were attentive to my needs, professional and responsive to my needs. Highly recommend Persona Law Group!","author":"","url":"https://estatelawboutique.com/"}]')), updated_at = datetime('now') WHERE slug = 'lafreniere-sanna-estate-law-ottawa' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Want to thank Sean for the very hard work he did on my case. He got me the best possible outcome and was honest with me right from the start. No sugar coating! He says he''s about being practical and thorough and that is exactly what he is. Thank you! D.K.","author":"","url":"https://ltllp.ca/"},{"text":"Sean was of great assistance to me and my family when I was in difficult times with my divorce and separation. Mr. Sean always had the patience to make me understand what is happening so I am less nervous when we go to court.","author":"","url":"https://ltllp.ca/"},{"text":"I have referred many of my friends and family members to LTLLP and rest assured, Daniel Tram and Sean Lakhan treated their matters with utmost priority and diligence. They patiently explained all the complicated legal issues, always stayed in contact and got the results the clients were seeking. Great work all across the board!","author":"","url":"https://ltllp.ca/"}]')), updated_at = datetime('now') WHERE slug = 'lakhan-tram-llp-mississauga' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I had the pleasure of meeting with Mr. Lalande. He was compassionate, honest, and straightforward. He made me feel comfortable and was supportive of my situation. I feel confident in his opinion and would not hesitate to recommend him and his lovely team.","author":"","url":"https://injured.ca/"},{"text":"Following a serious truck collision, I required extensive medical treatment for spinal cord damage. Their truck accident litigation experience was outstanding, and they fought relentlessly to achieve a fair settlement.","author":"","url":"https://injured.ca/"},{"text":"When I got fired, I was quite shocked and did not know what to do. After 16 years with the company, I found being terminated very emotionally stressful. I called Matt, and thankfully, he helped me get the severance I deserved.","author":"","url":"https://injured.ca/lawyer-to-review-severance-package/"}]')), updated_at = datetime('now') WHERE slug = 'lalande-personal-injury-long-term-disability-lawyers' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I hired Lambert Law to represent me in my ICBC claim on the recommendation of my chiropractor. I had tendinitis in my shoulder from the collision which developed calcification, and as a result limited the use of my arm in a variety of ways.","author":"","url":"https://lambertlaw.com/client-reviews/"},{"text":"I was recommended to Lambert Law by my friend’s dad. I was involved in a motor vehicle collision in 2018 on the Malahat, when a driver heading the opposite direction fell asleep at the wheel and struck the vehicle beside me.","author":"","url":"https://lambertlaw.com/client-reviews/"},{"text":"I was struck by a truck while crossing at a crosswalk in Langford. I waited for the signal to cross at the intersection of Phipps Road and Langford Parkway. When I was about 35% across the road a truck struck me when making a right hand turn onto Phipps Road.","author":"","url":"https://lambertlaw.com/client-reviews/"}]')), updated_at = datetime('now') WHERE slug = 'lambert-law-victoria' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Dear Erica, Big, sincere THANK YOU – from the bottom of my heart! I’m so grateful for your amazing supports, help and – of course – winning the case! I wish you nothing but many beautiful moments in your professional and personal life! p.s. I’ll never forget what you have done for me!","author":"","url":"https://lamontlaw.ca/"},{"text":"Dedicated, compassionate, professional. Erica and Michael met with us in the hospital during a tremendously distressing time and advocated for our sons rights from day one. We are extremely grateful to have had the Lamont team on our legal journey.","author":"","url":"https://lamontlaw.ca/"},{"text":"My wife and I became clients of Erica Lamont and her associate Braden Adsett of Lamont Law in Hamilton Ontario, and not only were they highly professional and thorough, they showed genuine compassion throughout the entire process. Thank you Erica and Braden.","author":"","url":"https://lamontlaw.ca/"}]')), updated_at = datetime('now') WHERE slug = 'lamont-law-hamilton' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I highly recommend Laredo Law. I met Lisa shortly after the devastating loss of my husband. Lisa and her team could not have been more caring and compassionate. They were always available to answer all my questions and concerns.","author":"","url":"https://laredolaw.ca/"},{"text":"I''ve been working with Lisa since 2016 and I am always happy with her. She has done my will and estate planning, and I have recommended her to family and friends.","author":"","url":"https://laredolaw.ca/"},{"text":"I am so grateful that I got to work with Lisa and her team. They are very knowledgable in their respective areas and were able to help me out with my issues. I highly recommend their service to my friends and family!","author":"","url":"https://laredolaw.ca/"}]')), updated_at = datetime('now') WHERE slug = 'laredo-law-toronto' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Tatiana is highly knowledgeable and professional. She was able to answer all our questions and made the entire immigration process much clearer and easier to navigate. Her guidance was truly invaluable.","author":"","url":"https://lawpoint.ca/reviews/"},{"text":"Thank you Tatiana Gulyaeva for helping me secure TRV (visitors visa) for my sister whose visa application was refused earlier in New Delhi, India (Feb''23).","author":"","url":"https://lawpoint.ca/reviews/"},{"text":"We sincerely thank Tatiana Gulyaeva for her work in obtaining a student visa. The journey was not easy, but the result was achieved: after three refusals, the study permit was granted!","author":"","url":"https://lawpoint.ca/reviews/"}]')), updated_at = datetime('now') WHERE slug = 'lawpoint-north-york' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Megha is incredibly knowledgeable, reliable, thorough, and assertive in her practice. While being objective, she has also shown empathy to us when it was needed. She very articulate and presents herself very well. Highly recommend.","author":"","url":"https://lawsnbeyond.com/"},{"text":"I want to express my sincere gratitude to Farah Razi. She was always supportive every step of the way. Despite the language barrier, she was incredibly patient with me and made sure I understood everything clearly.","author":"","url":"https://lawsnbeyond.com/"},{"text":"Megha Sharma is an excellent lawyer. Very knowledgeable and professional with a great insight, focus on delivery, timely and honest communication. All along, she provided me with the right advice, realistic expectations, and promised service. Thanks Megha!","author":"","url":"https://lawsnbeyond.com/"}]')), updated_at = datetime('now') WHERE slug = 'laws-and-beyond-calgary' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Un gros merci à toute l''équipe de m''avoir accompagné dans cette mésaventure. Votre écoute et disponibilité fu remarquable. Vous avez eu un travail colossal que vous avez relevé avec brio que maintenant me permets de pouvoir tourner la page et de vivre sainement.","author":"","url":"https://www.lecabinetm.com/"},{"text":"Service magnifique. Je fais affaire avec vous depuis Avril 2021 pour un dossier contre ivac. Sans votre travail j''aurais déjà abandonné. Avec votre connaissance et votre cœur les choses vont loin et tres bien. Se battre contre un système en faveur d''eux même au lieu des victimes est tout un combat! Tout sera bientôt réglé merci a vous.","author":"","url":"https://www.lecabinetm.com/"},{"text":"Service impeccable et professionnel. Je suis plus que satisfaite par les services du Cabinet M. Je ferais encore affaire avec eux au besoin, sans hésitation.","author":"","url":"https://www.lecabinetm.com/"}]')), updated_at = datetime('now') WHERE slug = 'le-cabinet-m-saint-jerome' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"We were first introduced to League and Williams when our boat (our summer family home) was destroyed. Our insurance company declined our claim leaving us emotionally and financially devastated. Darren Williams critically analyzed our circumstances and his tenacious efforts resulted in us receiving our full insurance payout. Thank you to Darren and the awesome League and Williams team.","author":"","url":"https://www.leaguelaw.com/"},{"text":"I was recently represented by Andrew Broadley in an injury accident claim. The service I received from Andrew and League and Williams staff Taryn Smith and Wendy Ferrara was at all times nothing short of exemplary. I felt throughout the whole process that my health and recovery were the foremost consideration.","author":"","url":"https://www.leaguelaw.com/"},{"text":"Don handled my late husband’s estate in a highly efficient manner. Also he always made me feel valued and I experienced peace of mind knowing that matters were in his hands. I have much appreciation for what he has done for me. Susan Dubois","author":"","url":"https://www.leaguelaw.com/"}]')), updated_at = datetime('now') WHERE slug = 'league-and-williams-lawyers-victoria' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I cannot recommend Lecker & Associates highly enough. I had the pleasure of dealing with Jon, who was absolutely exceptional. The staff is general were incredibly kind, professional, compassionate, and understanding throughout my interactions with them. What truly stood out was the genuine care, patience, and respect they demonstrated.","author":"Marni S.","url":"https://leckerslaw.com/"},{"text":"Want to personally thankMatthew and Eslita and Lecker and Associates who listened to my concerns and hep me find a resolution that I was happy with in a timely matter. Thank you again Matthew and Eslita!","author":"Drew L.","url":"https://leckerslaw.com/"},{"text":"It was a great experience for their service back in 2017. I had never used legal service for employment issues before in my life. I gave it a try and I found it very satisfied. You never know it until you try, They charged fee appropriately without more than they needed. Thank you Lecker!","author":"","url":"https://leckerslaw.com/"}]')), updated_at = datetime('now') WHERE slug = 'lecker-and-associates-north-york' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Miss Lee is a very dedicated and efficient lawyer. When I met her for the first time, I had a deportation case where a family of our church had only 48 hours time frame to leave Canada. Miss Lee had to work through the night in order to have the appeal ready in the morning for submission. Miss Lee fought...","author":"","url":"https://leecompany.ca/testimonials-peers/"},{"text":"I am very well connected in the South Asian community and I know that Lee & Company has a wonderful reputation in our community. They have worked on many, many cases and achieved remarkable results. I have seen them win appeals and re-unite families; win judicial reviews and bring deserving and grateful foreign nationals to join our Canadian community. They...","author":"","url":"https://leecompany.ca/testimonials-peers/"},{"text":"I am a Corporate/Real Estate lawyer practicing for the past 15 years in Richmond Hill, Ontario. When I get inquiries from clients about immigration problems, I refer them to Lee & Company. I have great confidence in their work and their ability to help clients find solutions to their problems. I have had clients call me back to thank me...","author":"","url":"https://leecompany.ca/testimonials-peers/"}]')), updated_at = datetime('now') WHERE slug = 'lee-and-company-north-york' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"We have been working with Lisa and her team for a year, and their efficiency, workflow, communication and their professionalism has made it an incredible experience. Hire them!","author":"","url":"https://legalfocus.ca/"},{"text":"Legal Focus was an incredible help in my home buying experience! Lisa took such care and went over everything in great detail with kindness and patience to ensure I felt comfortable and had an understanding. I would absolutely recommend Legal Focus!","author":"","url":"https://legalfocus.ca/"},{"text":"It was a pleasure dealing with everyone. The professionalism and attention to detail was first class. I highly recommend Legal Focus.","author":"","url":"https://legalfocus.ca/"}]')), updated_at = datetime('now') WHERE slug = 'legal-focus-llp' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"We tried to defend ourselves in civil court, but ultimately decided to hire Ryan — and it was the wisest decision we have made in the last two years of hell with our condo managers.","author":"","url":"https://legalsolutionslawfirm.ca/"},{"text":"Ryan did an outstanding job on my case. He was clear, professional, and always kept me informed. Thanks to his hard work, my charges were dropped. I’m very grateful and highly recommend him.","author":"","url":"https://legalsolutionslawfirm.ca/"},{"text":"I was going through anxiety not knowing what to expect with my case. Ryan explained everything simply and stood up for me at my hearing. I’m really thankful for his help!","author":"","url":"https://legalsolutionslawfirm.ca/"}]')), updated_at = datetime('now') WHERE slug = 'legal-solutions-law-firm-toronto' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
