UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Ça été formidable, vous êtes une bonne équipe. Vous m’avez mie en confiance, c’est pas évident pour moi de retourner dans une autre faillite. Merci beaucoup pour tout. Jules Langlois","author":"","url":"https://roysyndic.ca/"},{"text":"Je ne peux que remercier toute l’équipe de Roy Syndic pour la qualité de l’accompagnement proposé à toutes les étapes de nos démarches. Ce fut un vrai soulagement d’avoir trouvé des interlocuteurs aussi bienveillants, et qui ont su faire preuve de réactivité, flexibilité et professionnalisme à toutes les étapes. Anonyme","author":"","url":"https://roysyndic.ca/"},{"text":"Ma première impression est de vous trouver très efficace et je suis heureux de vous avoir pour me représenter. Merci beaucoup! Anonyme","author":"","url":"https://roysyndic.ca/"}]')), updated_at = datetime('now') WHERE slug = 'm-roy-and-associes-drummondville' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
