UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Fraser Gow is a great lawyer. Fraser is very professional, sincere, thoroughly, and great at communicating. I could not have been happier with the outcome of my case. Thank you to Fraser and his amazing team!","author":"","url":"https://www.mglawyers.ca/"},{"text":"Working with Fraser Gow and his team was a pleasure. They were very professional, highly experienced and always up front and honest. Even though my case took years they were there to support and answer questions when needed. I would highly recommend Fraser for an injury legal claim and I thank you Fraser for all of your support.","author":"","url":"https://www.mglawyers.ca/"},{"text":"I would like to say thank you to Fraser Gow and his team for the great job they did on my case. I went through 2 years of a stress free case cause he took care of everything I needed to be heard and validated in reguards to my injury.","author":"","url":"https://www.mglawyers.ca/"}]')), updated_at = datetime('now') WHERE slug = 'macisaac-gow-llp-oakville' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
