UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Being arrested for a DUI is very stressful. Especially if it''s your first time (like me). And when you don''t know much about how the law works, it can make life seem impossible. With Michael however, that wasn''t the case. After meeting with him, the worry and uncertainty disappeared.","author":"","url":"https://www.michaeldyck.ca/testimonials"},{"text":"I am very pleased with the service received from Michael Dyck. He is so compassionate, empathetic, and knowledgeable. I was very concerned and worried about my future. Michael helped me and he was able to have the charges dropped. I would highly recommend him to anyone.","author":"","url":"https://www.michaeldyck.ca/testimonials"},{"text":"Having no previous criminal record, I was very concerned and curious about what my future held when I was charged. The thought of going to court and dealing with legal matters was at times overwhelming. After my initial meeting with Michael however, I felt very at ease.","author":"","url":"https://www.michaeldyck.ca/testimonials"}]')), updated_at = datetime('now') WHERE slug = 'michael-dyck-criminal-law-winnipeg' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
