UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"My divorce with Mary went incredibly smoothly! She’s super competent and efficient, and she really cared about my personal story. I’m so happy to have found an attorney with her expertise and empathy! Thankful for MM Law.","author":"","url":"https://mmfamilyanddivorcelawyers.ca/"},{"text":"Fast and efficient service. Mary Ali was very helpful and professional. She gave me clear instructions on how to proceed and make the whole process easy and stress free. I had my divorce done with 3 months, was a lot easier than I though! No hidden fees. Strong recommended!","author":"","url":"https://mmfamilyanddivorcelawyers.ca/"},{"text":"I had a wonderful and easy experience! It was a manageable price and incredibly helpful! I had the lawyer Mr. Zihao Guo, he handled everything with kindness and I was kept informed with the entire process.","author":"","url":"https://mmfamilyanddivorcelawyers.ca/"}]')), updated_at = datetime('now') WHERE slug = 'mm-family-and-divorce-lawyers-calgary' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
