UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Murphy assisted with our home closing. He took time to explain and guide us through the process. Through his expertise, we were able to save cost and took possession at the exact time we wanted. Thanks Murphy and looking forward to closing the next one with you!","author":"","url":"https://mophlegal.ca/"},{"text":"Wendy and Moph (Muftau) made my loan paperwork experience so much less stressful. Clear, kind, prompt- thorough and doesn’t overcharge for unnecessary work. Would absolutely go to the team again for loan paperwork or real estate 🏡 legal. …","author":"","url":"https://mophlegal.ca/"},{"text":"Muftau is a fine real estate lawyer. He is very detailed, professional and supportive. He has represented me on 2 real estate transactions and, on both deals, I couldn''t have asked for a better lawyer. I highly recommend him.","author":"","url":"https://mophlegal.ca/"}]')), updated_at = datetime('now') WHERE slug = 'moph-legal-calgary' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"My experience with Andrew was outstanding. What should have been a rather open and close situation, by no fault of Andrews, became a drawn out mess. Through this, he continued to prove why he was the right choice in representation.","author":"","url":"https://ontariofamilylaw.ca/"},{"text":"This letter is to commend Rachel for her detailed and concise direction during my separation. Rachel’s advice was clear and detailed and I definitely felt protected navigating the separation process.","author":"","url":"https://ontariofamilylaw.ca/"},{"text":"When we went to our court dates Mr. Morrison handled himself in a professional manner. In my particular case his work quality was excellent and I obtained the outcome I wanted. If you are looking for a great divorce Lawyer, Mr. Morrison is someone you can trust to represent you with confidence.","author":"","url":"https://ontariofamilylaw.ca/"}]')), updated_at = datetime('now') WHERE slug = 'morrison-williams-llp-oakville' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I am so impressed with this legal team. Immediately the phone was picked up and I retained Hossein as a lawyer. Within 1 minute of hanging up, one of Hossein’s team members reached out and got the full story from me.","author":"","url":"https://motevallicriminallawyers.com/"},{"text":"I would like to Thank Mr.Motevalli Law group, for their hard work & dedication to my case , which was very complex, I was assured from the start when i retained him to represent my case I was in very good hands, Mr.Montevalli got my charges dropped within 4months.Mr.","author":"","url":"https://motevallicriminallawyers.com/"},{"text":"These guys solved my problem without me even having to leave my home. Top notch. Very happy with the results. Thank you","author":"","url":"https://motevallicriminallawyers.com/"}]')), updated_at = datetime('now') WHERE slug = 'motevalli-law-group-toronto' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Just want to thank you for handling my very delicate and impossible case. Who would ever think that after years of hiding and worrying my case will be approved and I would obtain Permanent Residency. -Anna & Ronald","author":"","url":"https://moyal.com/"},{"text":"More than 5 stars. Henry gave us straight and achievable advice which we took, our bit complicated immigration case which he handled ended up in a swift and favourable result. Totally highly recommended. Tonie Jun Farrol","author":"","url":"https://moyal.com/"},{"text":"I would highly recommend Mr. Henry Moyal to anyone who is looking for immigration legal services in Canada. This wonderful team is very experienced, professional, very approachable and they genuinely care for their clients. My experience with Henry has been fantastic. Huu phuoc nguyen","author":"","url":"https://moyal.com/"}]')), updated_at = datetime('now') WHERE slug = 'moyal-immigration-lawyers-north-york' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"George Battye, Chartered Accountant I have known Peter for many years and we have done a great deal of work together on clients who required complex [Canadian income tax structures] to achieve their goals, and others who needed our services to assist in divesting all or a part of their business, or to make an acquisition.","author":"","url":"https://munrocrawford.ca/testimonials/"},{"text":"Allen and Russet MacKay [Munro & Crawford] have advised us on so many things over the years both large and small. No matter the size of the problem [Munro & Crawford] were always there with calm and sensible advice. Resolving all manner of things – both business and personal.","author":"","url":"https://munrocrawford.ca/testimonials/"},{"text":"Simon Hong Ron and Olivia were excellent. They represented me as a buyer of shares to a recreational co-op during the period between Dec. 2022 - January 2023. I was quote with a fee upfront and the final billing was accurate. Both Ron and Olivia were professional, hard working and knowledgeable.","author":"","url":"https://munrocrawford.ca/testimonials/"}]')), updated_at = datetime('now') WHERE slug = 'munro-and-crawford-vancouver' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I worked with Bill Dick on an ICBC case after a car accident and I would highly recommend him. He was kind, caring, and guided me through the entire process with patience and professionalism. He negotiated my injury settlement and I achieved very good results. I’m extremely happy with the outcome. Thank you, Bill, for all your support","author":"","url":"https://www.murphybattista.com/?utm_source=GMBlisting&utm_medium=organic"},{"text":"I was seeking representation for medical malpractice and feel fortunate to have been represented by Kevin Gourlay. Although my case was challenging, Kevin walked me through each step, relaying the pros and cons in an easy to understand manner. Kevin is not only an excellent lawyer but also compassionate and kind.","author":"","url":"https://www.murphybattista.com/?utm_source=GMBlisting&utm_medium=organic"},{"text":"I had a great experience working with Bill Dick and his team. They were incredibly knowledgeable, professional, and kind throughout the entire process. I wouldn’t hesitate to recommend Bill to anyone looking for legal help. Thank you for everything!","author":"","url":"https://www.murphybattista.com/?utm_source=GMBlisting&utm_medium=organic"}]')), updated_at = datetime('now') WHERE slug = 'murphy-battista-llp' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
