UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Allison was perfect to work with. She was patient and helpful and although we have decided to put our matter on pause, I will be definitely re-retaining her in the future. A great comfort to have knowledgeable people in your corner during tough times times!","author":"","url":"https://shulman.ca/"},{"text":"I had the pleasure of working with Alyssa Bach regarding details of my prenup agreement with my now husband. Alyssa was mindful of my time and communicated well. She explained everything with ease and helped me feel comfortable with the inclusions of my needs within the prenup.","author":"","url":"https://shulman.ca/"},{"text":"If you need a family lawyer, do not go anywhere else but Shulman & Partners LLP. Alyssa gave me the best experience during a stressful time and delivered the exact results I wanted. Her response time is unmatched. she was incredibly fast at replying to all my emails and phone calls.","author":"","url":"https://shulman.ca/"}]')), updated_at = datetime('now') WHERE slug = 'shulman-and-partners-llp' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
