UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"The service was very professional; the staff were courteous and respectful. The communication on what was required for the home purchasing process was provided in a timely manner. Furthermore, proper explanations were provided for the documents that we signed. They made us feel like they were looking out for our best interests.","author":"","url":"https://singhalaw.ca/"},{"text":"I had the pleasure of working with Jay and I couldn’t be more impressed with his service. He was incredibly reliable, efficient, and consistently went above and beyond. No matter how late it was, Jay always picked up the phone and provided clear guidance for both me and my clients.","author":"","url":"https://singhalaw.ca/"},{"text":"I recently used Mr. Jayanta K Singha''s law firm for occupancy closing my condo purchase, and the experience was exceptional from start to finish. The communication was clear, timely, and professional. Every step of the process was explained in detail, and all documents were handled efficiently without any delays.","author":"","url":"https://singhalaw.ca/"}]')), updated_at = datetime('now') WHERE slug = 'singha-law-professional-corporation-toronto' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"We love Sitka! They were so helpful and insightful when starting our business from the ground up. We''d highly recommend to anyone! ... they''re pretty good at spin too!","author":"","url":"https://sitkalaw.ca/testimonials/"},{"text":"I met Gurpreet through my Rotary club, so when I decided to sell my condo privately, I asked her to help with the legal aspects. She and her team turned what could have been a nerve wracking process in to an orderly one.","author":"","url":"https://sitkalaw.ca/testimonials/"},{"text":"We have dealt with Christian on a few real estate transactions and have been very impressed! He is extremely knowledgeable and efficient and a pleasure to deal with. Highly recommended!","author":"","url":"https://sitkalaw.ca/testimonials/"}]')), updated_at = datetime('now') WHERE slug = 'sitka-law-group-victoria' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Adam expertly guided us through the IRCC intricacies of applying for and obtaining Permanent Residence status. We were very pleased with his availability and expertise throughout the process. Highly recommended.","author":"","url":"https://slipacofflaw.com/"},{"text":"From the moment I first opened the door to Adam’s office six years ago, I knew I was in the right hands. Over six long years of hard work, he guided me every step of the way toward my citizenship with unparalleled dedication, deep knowledge, and respect.","author":"","url":"https://slipacofflaw.com/"},{"text":"I highly recommend using Adam for any immigration needs! He helped my wife get her Canadian PR. During the whole process he was formal, respectful and very helpful. Very cost effective as well. Overall extremely satisfied with his effort and all of the help he gave us!","author":"","url":"https://slipacofflaw.com/"}]')), updated_at = datetime('now') WHERE slug = 'slipacoff-immigration-law-ottawa' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Ms. Smith was able to review my job offer and provide very helpful feedback. She was transparent about all aspects of the contract review and was able to provide valuable insight that helped me make a decision moving forward.","author":"","url":"https://smithemploymentlaw.ca/"},{"text":"Waheeda is very easy and friendly to approach. She provided me with lots of legal advices. I will definite go back to her if I need more consultation. Highly recommended.","author":"","url":"https://smithemploymentlaw.ca/about/client-testimonials/"},{"text":"I can''t imagine having chosen a different path than to seek out the services of Smith Employment Law. When I lost my employment under questionable circumstances I was at a loss as to what to do. That is, until I connected with Waheeda.","author":"","url":"https://smithemploymentlaw.ca/about/client-testimonials/"}]')), updated_at = datetime('now') WHERE slug = 'smith-employment-law-toronto' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"A commanding performance conducted by an artist in advocacy is a rare and precious item. In my 12 years of presiding over hundreds, maybe even close to a thousand proceedings on the bench, I have seen truly excellent advocacy on only a very few occasions. Mr.","author":"","url":"https://www.sil.lawyer/"},{"text":"Being injured is very stressful. Mike and his team treated me with respect, dignity and caring. I would get weekly calls to see how I was doing and was kept updated on my case. I was treated like family, not like a number.","author":"Dan P.","url":"https://www.sil.lawyer/"},{"text":"From start to finish which was a long time due to the severity of my case, Michael and his team were very communicative, helpful in all aspects and understanding of my situation.","author":"Lauri P.","url":"https://www.sil.lawyer/"}]')), updated_at = datetime('now') WHERE slug = 'smitiuch-injury-law-etobicoke' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I’m extremely thankful for helping me get my PR approval and my mom’s Super Visa. The entire process was handled with care and professionalism. They were always available to answer my concerns and kept me updated throughout. Their guidance made everything much easier for me. I highly recommend their services!","author":"","url":"https://snowdropimmigration.ca/"},{"text":"I had a great experience with Snowdrop Immigration. They worked on my PR, work permit, and my mother-in-law’s Super Visa application, and everything was handled very professionally. The team was patient, supportive, and always available to answer my questions. I’m very thankful for their help and would definitely recommend them to others.","author":"","url":"https://snowdropimmigration.ca/"},{"text":"I worked with Kaushika and muskan for my parents supervisa. Both girls and the whole snowdrop team were so professional, responsive and very clear in what they do. Thankfully Both my parents got their visa on time. Great work. Must reach to Snowdrop. They know what they are doing.","author":"","url":"https://snowdropimmigration.ca/"}]')), updated_at = datetime('now') WHERE slug = 'snowdrop-immigration-services-ltd-edmonton' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I feel truly lucky to have worked with Mr. Ali and Mr. George during one of the most difficult and complex legal cases I’ve faced. From the very beginning, I felt supported and knew I could truly trust them.","author":"Reza S.","url":"https://sodagar.ca/"},{"text":"Ali and his professional team have been supporting me with my businesses and real estate matters since 2015. They''ve consistently provided me with the best advice and top-notch service. If you''re looking for a highly professional lawyer, I strongly recommend Ali Sodagar.","author":"Milad S.","url":"https://sodagar.ca/"},{"text":"I can''t recommend Ali Sodagar and his team enough! My experience was beyond outstanding. The team handled our conveyance with unparalleled professionalism and efficiency. As a fellow lawyer, I deeply respect their expertise and commitment. Highly recommended!","author":"Arash E.","url":"https://sodagar.ca/"}]')), updated_at = datetime('now') WHERE slug = 'sodagar-and-company-law-corporation-vancouver' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Stacey helped me with my case with my previous employer. He worked incredibly hard on my case and helped me fight the wrongful dismissal, eventually settling at a very good deal. I was impressed by his professionalism and integrity.","author":"Beijia Z.","url":"https://www.wrongfuldismissal.ca/"},{"text":"Stacey and his team did a fantastic job with my case. Their professionalism and many years of experience helped me settle. I would highly recommend seeking advice before signing any documents.","author":"R C.","url":"https://www.wrongfuldismissal.ca/"},{"text":"Working with Stacey Ball was the best decision for my employment-related case. He was responsive, addressed all my concerns promptly and secured a fair resolution.","author":"PATRYK S.","url":"https://www.wrongfuldismissal.ca/"}]')), updated_at = datetime('now') WHERE slug = 'stacey-r-ball-toronto' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I had a positive experience working with Simran Sandhu. She was professional, knowledgeable, and approachable throughout the process. I appreciated her guidance, clear communication, and willingness to address my questions. Navigating legal matters can be stressful, and having someone who takes the time to explain the process makes a real difference.","author":"","url":"https://sternshapraylaw.ca/"},{"text":"Simran was so nice and understanding of my situation she helped me and handled everything so well couldn’t have asked for a better lawyer :) Thank you","author":"","url":"https://sternshapraylaw.ca/"},{"text":"I could not be more pleased with how Simran has helped me with my lengthy court case! Back in 2024 I was caught up in a criminal charge along with hybrid traffic violations. I was potentially looking at 18months prison time. She was able to get me a conditional discharge from the judge with probation.","author":"","url":"https://sternshapraylaw.ca/"}]')), updated_at = datetime('now') WHERE slug = 'stern-shapray-criminal-lawyers-surrey' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
