UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"After years of feeling completely defeated and discouraged with the family court system I retained Jagriti Jaswal and finally feel like I really have someone in my corner. Thanks to Jagriti I''m FINALLY seeing progress which is absolutely life changing for my young son and I. We can''t thank you enough!","author":"","url":"https://www.surroviklawcorporation.ca/"},{"text":"Jagriti has been a great asset for the kids and I and protecting us! I highly recommend her. She is very punctual.","author":"","url":"https://www.surroviklawcorporation.ca/"},{"text":"Ms. Jagriti is very good. She never left me and she really fought for my rights until I got what was right for me and for my children. inside the court she is the professional and outside the court room she will consider you a friend not a client. So thankful to have her.","author":"","url":"https://www.surroviklawcorporation.ca/"}]')), updated_at = datetime('now') WHERE slug = 'surrovik-law-corporation-surrey' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I am so glad I chose Susan Karpa as my criminal defence lawyer! I have never been on the other side of the law before. It was very difficult but she was very empathetic and compassionate, she always had my back. Her expertise, attention to detail, and dedication to me and my case gave me confidence.","author":"","url":"https://www.susankarpa.com/"},{"text":"I highly recommend Susan To anyone who needs help in a difficult situation. She was extremely knowledgeable, had clear direction and a plan, and persevered to get the results that I needed. My charges were withdrawn which allowed me to get back to my work and life .","author":"","url":"https://www.susankarpa.com/"},{"text":"I highly recommend Susan Karpa. I was facing two very serious criminal driving charges and was incredibly stressed about the future and my career. From our very first meeting, Susan was reassuring and immediately put a solid plan in place.","author":"","url":"https://www.susankarpa.com/testimonials/"}]')), updated_at = datetime('now') WHERE slug = 'susan-karpa-calgary' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"John Nelson’s legal council was essential in winning my case. His assistance was unfaltering and sincere. Subsequent aid with any legal matter is always quickly and efficiently provided. I highly recommend him as legal council.","author":"","url":"https://www.swiftsurelaw.ca/"},{"text":"I have been assisted by John Nelson for years. Family court is the worst place on earth, and I wanted The assistance of someone who is knowledgeable and fierce. John is it","author":"","url":"https://www.swiftsurelaw.ca/"},{"text":"I can’t recommend Swiftsure Law highly enough. It’s an incredibly warm and friendly, yet at the same time, professional firm with experienced lawyers who go out of their way for their clients.","author":"","url":"https://www.swiftsurelaw.ca/"}]')), updated_at = datetime('now') WHERE slug = 'swiftsure-law-victoria' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"With former experience representing major insurance companies in defending personal injury claims, I now only represent Plaintiffs. I know how to deal with insurance companies to get you the best settlement possible.","author":"","url":"https://szakacslaw.ca/"},{"text":"To my legal advisor Mr. Dale Szakacs and staff, I''m very very pleased with my experience with the Szakacs Law Firm. My Lawyer Mr. Dale Szakacs has been very attentive and thorough in his communication with me throughout the entire legal process.","author":"","url":"https://szakacslaw.ca/"},{"text":"Dale and his team have done a very good job and diligently on my file. I couldn''t be happier about the outcome of my claim. I can highly recommend Dale and his legal team. Thank you very much.","author":"","url":"https://szakacslaw.ca/"}]')), updated_at = datetime('now') WHERE slug = 'szakacs-law-injury-lawyers-calgary-calgary' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"how can we Help you? Let''s start the conversation Get legal help with compassion and care! First Name Last name Email Address Telephone Number Service Area Select one... Wills / Estate Planning Probate / Estate Management Real Estate Divorce & Separation Services Marriage Contracts, Prenuptial & Cohabitation Agreements Other How Can We Help You?","author":"","url":"https://www.tabuchilaw.com/"}]')), updated_at = datetime('now') WHERE slug = 'tabuchi-law-mississauga' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I live in Whitehorse, Yukon, where I work as a truck driver. My livelihood was at risk when I was charged with impaired driving and faced the devastating reality that I may lose my license for at least a year. Luckily, I was referred to David Tarnow by a friend who had used his services in Vancouver.","author":"","url":"https://www.tarnowcriminallaw.com/testimonials/"},{"text":"I was at a dinner party at a friend’s house, had a few glasses of wine, and made the poor decision of driving home — and was stopped by police just around the corner from where I live. I blew over the legal limit and was charged with a DUI.","author":"","url":"https://www.tarnowcriminallaw.com/testimonials/"},{"text":"After speaking with a few lawyers regarding the appeal of my 90-day Immediate Roadside Prohibition (IRP), I felt most comfortable with Jason.","author":"","url":"https://www.tarnowcriminallaw.com/testimonials/"}]')), updated_at = datetime('now') WHERE slug = 'tarnow-criminal-law-richmond' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"It has been a pleasure to get Sunny''s guidance in our recent real estate transaction. Recognizing that legal dealings can be complex and daunting, we really appreciated his accessibility, responsiveness, and clear communication throughout the process. We look forward to working with you again in the future, Sunny!","author":"Lara M.","url":"https://tathgarlaw.com/"},{"text":"Sunny is a extremely knowledgeable and personable lawyer. He was able to help with all real estate/HoldCo/trust questions I had and break down the benefits and estates/tax considerations for each.","author":"Deepak N.","url":"https://tathgarlaw.com/"},{"text":"Sunny was super organized and clear for us as first time homeowners with tight closing and possession dates. He identified related estate planning needs which are often tricky when a blended family is purchasing a home but we felt well informed and confident in our decision making. And a good sense of humor helps make the process better!","author":"Amy A.","url":"https://tathgarlaw.com/"}]')), updated_at = datetime('now') WHERE slug = 'tathgar-law' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
