UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Lawyer Zhao is a very responsible lawyer. Whenever I have questions, I can call him and he''ll explain them to me. This makes me feel safe while living in a foreign country. He''s very efficient. I''m lucky to have met him while I''m abroad. Yumei Xiao","author":"","url":"https://tczlaw.ca/testimonial/"},{"text":"Eric is an honest and capable young man. He utilized his experience, research, and assistance from his senior lawyer friends to provide me with the best strategy for my divorce lawsuit. I highly recommend him to anyone who needs a family lawyer St El","author":"","url":"https://tczlaw.ca/testimonial/"},{"text":"I have worked with Mr. Zhao for the past six months. He is a very professional, responsible, and details oriented lawyer. He is on top of his every case. He will talk and listen to your concern personally.","author":"","url":"https://tczlaw.ca/testimonial/"}]')), updated_at = datetime('now') WHERE slug = 'tcz-law-toronto' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Sarah has done great work on our matter. She is a great listener who really understood what we needed. She also got great results. I am recommending Sarah to everyone I know. Former Client","author":"","url":"https://thelawportal.ca/"},{"text":"The success of the outcome of the JCC was entirely due to Ms. Miller’s through and professional preparation and I have great respect and gratitude for her services. I’ve recommended her legal support to friends in marital distress. Former Client","author":"","url":"https://thelawportal.ca/"},{"text":"Sarah was very knowledgeable and helpful through my separation. She was amazing with me and my family and have referred two of my friends to her and they are just a happy with her service as i was. Former Client","author":"","url":"https://thelawportal.ca/"}]')), updated_at = datetime('now') WHERE slug = 'the-law-portal-vancouver' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I highly recommend The Legal Pillars for your legal needs. Mr. Angad Singh have been extremely helpful to my family. They went above and beyond to provide us with valuable information in a timely manner when we needed their guidance the most. We truly appreciate him and highly recommend him.","author":"","url":"https://thelegalpillars.com/"},{"text":"I would recommend this Law Firm 11 out of 10. They truly care for your best interests. They worked hard and diligently on my case and I’m sure they would for everyone’s case. Do not hesitate to call The Legal Pillars team!!! They’re the best!!","author":"","url":"https://thelegalpillars.com/"},{"text":"Very impressed with the service we received for our property closing from The Legal Pillars team and lawyer Angad Singh. After closing, he followed up to make sure everything was fine, and we got our legal package with all signed documents a few days later. Angad Singh and The Legal Pillars provide professional service.","author":"","url":"https://thelegalpillars.com/"}]')), updated_at = datetime('now') WHERE slug = 'the-legal-pillars-pc-mississauga' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Paul, Liz and the whole Riley firm have been supporting me over the past two years with a very difficult family law situation.","author":"","url":"https://www.therileyfirm.ca/testimonial-page/"},{"text":"I contacted Paul during one of the roughest periods of my life. Paul showed me compassion and understanding. He also treated me with respect; and assured me that all will be well.","author":"A. E.","url":"https://www.therileyfirm.ca/testimonial-page/"},{"text":"I don''t think a single review would do this law firm justice. I am greatly thankful for everything they offered me. Even though my family matter was complex and it had many areas to touch, Paul was able to cover it all and get me exactly what I needed.","author":"Ashwaq. A.","url":"https://www.therileyfirm.ca/testimonial-page/"}]')), updated_at = datetime('now') WHERE slug = 'the-riley-divorce-and-family-law-firm' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Clients come to us for clarity and leave with advice they can trust. Jaskaran Sandhu Managing Partner","author":"","url":"https://tidallaw.ca/"},{"text":"Guntash Gill is an outstanding family lawyer! Professional, knowledgeable, and genuinely caring throughout the entire process. I highly recommend her to anyone needing family law assistance","author":"","url":"https://tidallaw.ca/"},{"text":"Guntash''s expertise and professionalism is unmatched! She explained everything thoroughly and always made me comfortable during a somewhat intimidating process. A great family lawyer!","author":"","url":"https://tidallaw.ca/"}]')), updated_at = datetime('now') WHERE slug = 'tidal-law-llp-edmonton' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
