UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Roger was exceptional in helping my dad with a challenging employment matter. He was professional, clear, and compassionate, guiding us every step of the way. Thanks to his expertise, we achieved a great outcome. Highly recommend! JP Jeff P","author":"","url":"https://tzlawyers.ca/"},{"text":"I had a great experience with TZ Law and Roger. He was incredibly helpful, professional, and truly had my best interests in mind throughout the entire process. His attention to detail, clear communication, and dedication made everything smooth and stress-free. I highly recommend Roger and the team at TZ Law to anyone looking for reliable and client-focused legal services!","author":"","url":"https://tzlawyers.ca/"},{"text":"Roger is knowledgeable and responsive. He genuinely cares about helping me. Communication is easy, clear, and comfortable. I wouldn’t hesitate to recommend him! MM Melissaa Ma","author":"","url":"https://tzlawyers.ca/"}]')), updated_at = datetime('now') WHERE slug = 'tz-law-calgary' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"My wife and I contacted Matkowsky Immigration Law after receiving a denial due to missing documents. Mackenzie Stern was amazing to work with, she was professional, friendly, and organized. She helped us appeal the decision and we were able to achieve an early resolution.","author":"","url":"https://uilawyers.com/"},{"text":"⭐⭐⭐⭐⭐ I had a great experience working with this team throughout my permanent residency process. Everyone was professional, knowledgeable, and supportive from start to finish. They were always responsive to my questions, provided clear guidance, and made sure I was informed every step of the way.","author":"","url":"https://uilawyers.com/"},{"text":"Yasmin Rahim from the Matkowsky team was professional, courteous, and most importantly, kind. She was there for all of the hard questions, while dilligently working on my outbound spousal sponsorship case. Thank you Yasmin for helping my wife and I unite!","author":"","url":"https://uilawyers.com/"}]')), updated_at = datetime('now') WHERE slug = 'unified-immigration-lawyers-toronto' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
