UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Truly a caring and compassionate law firm to deal with, They dont blur the lines of whats immoral Nor do they sugar coat the situations at hand. If you are looking for a law firm that has YOUR best interests at heart then i couldn''t honestly recommend this law firm more!","author":"","url":"https://victorialaw.ca/"},{"text":"Velletta Pedersen Christie has been instrumental in my complicated legal process that involved linked areas of corporate, family and property law, which they have masterfully helped me navigate in short time frames with high efficiency and effectiveness.","author":"","url":"https://victorialaw.ca/"},{"text":"Excellent service. Worked with Natalia and she guided me through my real estate closure. Really didn’t know what steps needed to be taken, and Nat was patient and moved mountains (during the holidays) to get the work done. So appreciative! Would recommend every time.","author":"","url":"https://victorialaw.ca/"}]')), updated_at = datetime('now') WHERE slug = 'velletta-pedersen-christie-lawyers-victoria' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Vick Hundal was highly professional from the first time we spoke on the phone through to my trial. He represented me with maximum effort. Thanks to Mr. Hundal, my charges were dismissed.","author":"Raman G.","url":"https://vickhundallaw.ca/"},{"text":"Mr. Hundal fought my legal battle with honesty. He did not let me down and during the proceedings. He kept me updated on the proceedings and was always available to answer any questions. Thank you Vick for all of your help!","author":"Junaid Q.","url":"https://vickhundallaw.ca/"},{"text":"I highly recommend the law office of Vick Hundal to anyone looking for honest, reliable, and professional service. Vick will represent you with integrity and provide the best possible advice with the best outcome.","author":"Jatin K.","url":"https://vickhundallaw.ca/"}]')), updated_at = datetime('now') WHERE slug = 'vick-hundal-brampton' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I am very grateful for Igor Vilkhov guidance and support throughout my case. Their professionalism, knowledge, and responsiveness made a difficult situation much easier to navigate. I highly recommend their services to anyone needing a skilled and trustworthy lawyer.","author":"","url":"https://vilkhovlaw.ca/"},{"text":"My son was facing an extremely serious charge that could’ve ruined his future. Igor and his team handled the matter so well that my son walked away a free man. I honestly can’t thank him enough for his very very hard work. All the way from Orillia. Thank you Igor!!!","author":"","url":"https://vilkhovlaw.ca/"},{"text":"I express my deep gratitude to Igor Vilkhov for his work on my case. He did a great job and achieved a fair outcome and the dismissal of all charges against me. Igor was in constant contact, kept me informed of every step, and was ready to answer any questions I had.","author":"","url":"https://vilkhovlaw.ca/"}]')), updated_at = datetime('now') WHERE slug = 'vilkhov-law-professional-corporation-toronto' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"One of the most amazing and my first experience with a lawyer went amazing. They were extremely helpful. I''ll recommend it 100 percent.","author":"","url":"https://vincentmarklaw.ca/"},{"text":"I had a fantastic experience working with Aikay Vincent Oduoza on transferring the mortgage for a property. We ran into unprecedented challenges with the land title office (due to issues on my behalf), but Aikay went above and beyond to help us get the job done.","author":"","url":"https://vincentmarklaw.ca/"},{"text":"They were so helpful regarding my experience… Even they were so professional, I will definitely suggest everyone to choose your law farm for theirs issues .. I am pleased properly with their work and behaviour both ! Best wishes….","author":"","url":"https://vincentmarklaw.ca/"}]')), updated_at = datetime('now') WHERE slug = 'vincent-mark-law-corporation-burnaby' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Thank you to the wahab team for helping me with my case. Professional, responsive, and knowledgeable throughout. Highly recommend.","author":"","url":"https://wahablaw.com/"},{"text":"Thank you to the team at Wahab Law for helping us to purchase our first home. Everyone was professional, patient, and easy to work with. They took the time to explain everything clearly and made sure we understood each step of the process. Their support gave us confidence and made the experience much less stressful.","author":"","url":"https://wahablaw.com/"},{"text":"It was my first time buying a home and I was totally lost but the team at Wahab Law was so professional and patient with me. Despite some setbacks they were able to work with my circumstances and close. I very much appreciate their assistance and would recommend them to anyone looking to buy or sell a home.","author":"","url":"https://wahablaw.com/"}]')), updated_at = datetime('now') WHERE slug = 'wahab-law-kitchener' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"The best thing you can do after a car wreck is contact a lawyer… signing on with Warnett Hallen LLP in Vancouver is the best thing I’ve ever done for myself. I swear to god. I just went in to see a doctor and for the first time I didn’t feel heard or listened to.","author":"","url":"https://warnetthallen.com/?utm_source=local&utm_medium=organic&utm_campaign=gbp_vancouver"},{"text":"My experience with Warnett Hallen LLP was first rate, from the moment I contacted them following a serious cycling accident due to the hazardous worksite of a maintenance contractor. The first law firm I spoke with about the accident showed little interest, but Manjot Hallen was supportive from the beginning.","author":"","url":"https://warnetthallen.com/?utm_source=local&utm_medium=organic&utm_campaign=gbp_vancouver"},{"text":"Five years ago, I was in a brutal car crash, which has changed my life forever. Throughout it all, there were a lot of ups and downs. One aspect that stayed solid and on course was Paul Warnett’s attitude and passion for my case. He never once wavered his professional attitude on what he believed I deserved.","author":"","url":"https://warnetthallen.com/?utm_source=local&utm_medium=organic&utm_campaign=gbp_vancouver"}]')), updated_at = datetime('now') WHERE slug = 'warnett-hallen-llp' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"David Sowemimo was extremely helpful with my case. He was very personable and took the time to explain everything to me. I felt confident that he had my best interests at heart and worked to get the best settlement. All the staff were easy to deal with and made the entire experience better.","author":"","url":"https://watchmakerlaw.com/"}]')), updated_at = datetime('now') WHERE slug = 'watchmaker-law-car-accident-and-personal-injury-lawyers-edmonton' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
