UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"My partner and I recently worked with Westcoast Wills and Estates to prepare our wills, powers of attorney, and representation agreements, and we couldn’t be happier with the experience. Bronte was absolutely fantastic–personable, professional, and incredibly thorough.","author":"","url":"https://westcoastwills.com/"},{"text":"Jackson Sinclair and his support team are great to deal with. He assisted both my elderly mother and disabled brother through the process of updating/preparing all documentation necessary and appropriate for their later years and end of life wishes, and did so respect and compassion.","author":"","url":"https://westcoastwills.com/"},{"text":"Just finished getting our Will and associated documents completed. We found Jessica to be professional, knowledgeable, and very pleasant. She explained well all the options and answered any questions we had. Pricing was up front and no extra hidden charges. Very good.","author":"","url":"https://westcoastwills.com/"}]')), updated_at = datetime('now') WHERE slug = 'westcoast-wills-and-estates-vancouver' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Our Lawyer, Muthana Mohamed, was a pleasure to work with. He handled both the sale and purchase of our homes and everything went very smoothly. We had a discrepancy with our new house that we may have ignored but on his advice, we were able to recover our loss very quickly and efficiently.","author":"","url":"https://whitestonelaw.ca/"},{"text":"I had the pleasure of hiring Muthana as my lawyer. He was great at keeping me up to date and he was on top of everything. The customer service was incredible and the knowledge he shared throughout the process even through the difficult parts easier to digest and understand the options we had.","author":"","url":"https://whitestonelaw.ca/"},{"text":"Our experience with Muthana was excellent. He accommodate us in our extra ordinary case within the short period of time, he managed to do the closing of our house. We are very thankful and we highly recommend him.\" Vivian Endrinal","author":"","url":"https://whitestonelaw.ca/"}]')), updated_at = datetime('now') WHERE slug = 'whitestone-law-ottawa' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Best in the Business! Best in the business!! Had the pleasure of working with Robin Jawanda, Karen Aujla & Dharm Dhillon with my own business as well as my clients business. They go above and beyond for their clients and provide the best service and professionalism. Highly recommend firm for all your needs.","author":"Jag B.","url":"https://wilsonrasmussen.com/"},{"text":"Clear, Concise Advice I''ve worked with several capable law offices in my life, but this firm truly stands out. Their clear, concise advice and responsive actions are exceptional. I cannot say enough good things about this outstanding team.","author":"Gerry L.","url":"https://wilsonrasmussen.com/"},{"text":"Legal Guidance Without the Stress Robin Jawanda and Dharam Dhillon are exceptional lawyers. Their expertise in real estate and contracts have made my life stress-free. They are thorough, responsive, and always have their clients'' best interests in mind. Highly recommend!","author":"Mandeep H.","url":"https://wilsonrasmussen.com/"}]')), updated_at = datetime('now') WHERE slug = 'wilson-rasmussen-llp-surrey' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
