UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Above and beyond anything I ever expected. Mr. Yazdani turned a nightmare of a disability claim into a quick, fair settlement in record time. He is kind, professional and always available. I highly recommend him for individuals being mistreated, manipulated or taken advantage of by anyone in the insurance industry. P. Brinacombe","author":"","url":"https://disabilitylawyertoronto.ca/"}]')), updated_at = datetime('now') WHERE slug = 'yazdani-law-north-york' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Highly recommended! All details were explained in a professional manner to me, and my lawyer handled my case excellently!","author":"","url":"https://www.yeungassociates.com/"},{"text":"My mom had an excellent experience working with them. She felt well-supported and confident throughout. Their expertise and dedication truly stood out, and I’m very grateful for their help. Highly recommended!!!","author":"","url":"https://www.yeungassociates.com/"},{"text":"Highly recommend very helpful, my case is all settled with good ending . Gloria is great , she helps a lot and explains all the details. Very professional","author":"","url":"https://www.yeungassociates.com/"}]')), updated_at = datetime('now') WHERE slug = 'yeung-and-associates-law-professional-corporation-toronto' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Raman Sehmbi and her team were very helpful in providing me with legal advice and services. She is very caring and an excellent communicator. I would recommend her as an attorney who is easy to deal with and provides great service. -","author":"","url":"https://www.ylaw.ca/about/law-firm-testimonials/"},{"text":"I never thought I would need a Lawyer … until I did. I didn’t know where to start, I had so many questions and fears. The moment I called YLaw some of those fears were put at ease and once I had my first meeting with Raman, I knew I was in great hands.","author":"","url":"https://www.ylaw.ca/about/law-firm-testimonials/"},{"text":"I had a very positive experience with YLaw. Ramanjot was very professional and I would not hesitate to refer her services to family or friends. The outcome of our case was life changing and I have her, her assistant Kate and the entire team at YLaw to thank for it. -","author":"","url":"https://www.ylaw.ca/about/law-firm-testimonials/"}]')), updated_at = datetime('now') WHERE slug = 'ylaw-vancouver' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Where do I start. The professionalism, commitment and dedication of Martin is impeccable. These are the kind of lawyers we need here in Canada. He upholds the standards and ensures he provides the right direction to his clients. I want to publicly thank you Martin for helping me through my litigation process. Work with Martin and you won’t regret it.","author":"","url":"https://zlegal.ca/"},{"text":"Martin was professional… very informative… personable & answered all my questions.He was candid about the accuracy of his response which enabled me to feel confident about making the right decision. Thank you Martin for your candour.","author":"","url":"https://zlegal.ca/"},{"text":"I found Martin’s firm on internet several years ago when my husband needed Employment Law Lawyer.","author":"","url":"https://zlegal.ca/"}]')), updated_at = datetime('now') WHERE slug = 'z-legal-litigation-lawyer-toronto' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Working with Luke Zacharias, and his paralegal Lorri Luxford was an excellent experience. They were patient, kind, and always took the time to answer my questions. I never felt rushed or overlooked. Their professionalism and dedication gave me complete confidence throughout my case. I’m very grateful for their support and would recommend them without hesitation.","author":"","url":"https://zmllp.ca/?utm_source=GBP&utm_medium=GBP&utm_campaign=GBP_Abbotsford&utm_id=GBP_Abbotsford"},{"text":"I had a great experience working with Zacharias Vickers McCann LLP. The team was professional, efficient, and made the entire process smooth and stress-free. A special thank you to Lorri Luxford — she was very kind, helpful, and always took the time to explain things clearly. I really appreciated her support and guidance throughout.","author":"","url":"https://zmllp.ca/?utm_source=GBP&utm_medium=GBP&utm_campaign=GBP_Abbotsford&utm_id=GBP_Abbotsford"}]')), updated_at = datetime('now') WHERE slug = 'zacharias-mccann-llp' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"I am absolutely convinced that these criminal lawyers are the best in the GTA I had the best experience with them in terms of professionalism and honesty from the jump all.","author":"","url":"https://zamani-law.com/"},{"text":"I called Mr. Zamani not knowing what to do. Never having been in a situation like this before I was terrified. A family member needed my help and I needed his help. Mr. Zamani put me at ease with the first conversation. His is extremely professional, compassionate and knowledgeable. He was in constant contact with updates to help ease anxiety.","author":"","url":"https://zamani-law.com/bails-reviews/"}]')), updated_at = datetime('now') WHERE slug = 'zamani-law-toronto' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Zemp Law Group did a remarkable job getting my Permanent Residence Application approval. They found an error on the application I submitted by myself, they fixed it, submitted it again and I got my PR approval. They’re very professional, knowledgable and efficient. Thank you!","author":"","url":"https://www.zemplaw.com/"},{"text":"I received help with obtaining my immigration document from Matthew Lebaron and Kevin Zemp. They were both professional, personable, and responsive. They walked me through each step and their strategy/advice led to a very positive result for me. If you need assistance with immigrating to Canada, I highly recommend them.","author":"","url":"https://www.zemplaw.com/"},{"text":"I’m so grateful for the service they gave us, they have great communication, and helped us with my husbands PR application, and we couldn’t have done it without them","author":"","url":"https://www.zemplaw.com/"}]')), updated_at = datetime('now') WHERE slug = 'zemp-law-group-calgary' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Zoe was very knowledgeable and professional, and yet was able to show compassion regarding my issue. She gave me assurance and confidence in how I wanted to proceed. Highly recommend this firm. 5 stars!","author":"","url":"https://arghandewal.ca/"},{"text":"Zoe was extremely helpful and knowledgeable, and took the time to answer all my questions and provide further explanation if needed. Thanks so much Zoe.","author":"","url":"https://arghandewal.ca/"},{"text":"Zoe didn’t only listen, she made me feel heard! She’s very professional and answered all of my questions with a lot of detail, it is clear that she knows what she is doing. I highly recommend arghandewal law!!","author":"","url":"https://arghandewal.ca/"}]')), updated_at = datetime('now') WHERE slug = 'zoe-arghandewal-nanaimo' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
UPDATE firms SET data = json_set(data, '$.comments', json('[{"text":"Anya and her law firm was wonderful to work with! She was very efficient and knowledgeable and helped me out with a time sensitive situation. I highly recommend Anya!","author":"","url":"https://www.zubiclaw.com/"},{"text":"Anya stands out as one of the most knowledgeable lawyers I have had the privilege of working with on legal matters. Her remarkable attention to detail and commitment to streamlined processes is truly impressive and unlike most lawyers.","author":"","url":"https://www.zubiclaw.com/"},{"text":"I highly recommend Anya to handle any real estate transaction. She goes above and beyond for my clients, has excellent communication skills & is truly such a pleasure to work with!","author":"","url":"https://www.zubiclaw.com/"}]')), updated_at = datetime('now') WHERE slug = 'zubic-law' AND COALESCE(json_extract(data, '$.commentsOff'), 0) = 0;
